import React, { useState } from 'react';

const Login = ({ isOpen, onClose, onLogin, isLoading, errorMsg }) => {
  const [user, setUser] = useState('');
  const [pass, setPass] = useState('');
  const [id, setId] = useState('');
  const [showPass, setShowPass] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    onLogin({ user, pass, id });
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h2>Iniciar Sesión</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Usuario"
            value={user}
            onChange={e => setUser(e.target.value)}
            required
            autoFocus
          />
          <div style={{ position: 'relative' }}>
            <input
                type={showPass ? "text" : "password"}
                placeholder="Contraseña"
                value={pass}
                onChange={e => setPass(e.target.value)}
                required
                style={{ paddingRight: 36 }}
            />
            <button
                type="button"
                className="showpass-btn"
                onClick={() => setShowPass(v => !v)}
                tabIndex={-1}
                aria-label="Mostrar/Ocultar contraseña"
            >
                {showPass ? "🙈" : "👁️"}
            </button>
            </div>
          <input
            type="text"
            placeholder="ID de Partición"
            value={id}
            onChange={e => setId(e.target.value)}
            required
          />
          {errorMsg && <div style={{ color: 'red', marginBottom: 8 }}>{errorMsg}</div>}
          <button
            type="submit"
            disabled={!user || !pass || !id || isLoading}
          >
            {isLoading ? "Validando..." : "Entrar"}
          </button>
          <button type="button" onClick={onClose} disabled={isLoading}>Cancelar</button>
        </form>
      </div>
    </div>
  );
};

export default Login;
